<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/JalaliDate.php';require_once __DIR__.'/../core/HrModule.php';Auth::requirePermission('hr_assessments.manage');$pageTitle='آزمون‌های سازمانی';$user=Auth::user();
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){http_response_code(419);exit('درخواست نامعتبر است.');}$scope=$_POST['assignment_scope']??'employee';$value=trim($_POST['scope_value']??'');$testId=(int)$_POST['test_id'];$period=trim($_POST['period_key']??'');$due=JalaliDate::toGregorian($_POST['due_date']??'')?:null;try{$sql='SELECT * FROM users WHERE role="employee" AND status="active"';$params=[];if($scope==='employee'){$sql.=' AND id=?';$params[]=(int)$value;}elseif($scope==='department'){$sql.=' AND department=?';$params[]=$value;}elseif($scope==='role'){$sql.=' AND role_key=?';$params[]=$value;}elseif($scope==='sales_line'){$sql.=' AND sales_line=?';$params[]=$value;}elseif(in_array($scope,['supervisor_team','manager_team'],true)){$sql='SELECT u.* FROM users u JOIN manager_employees me ON me.employee_id=u.id WHERE me.manager_id=? AND u.status="active"';$params[]=(int)$value;}$employees=Database::fetchAll($sql,$params);$employees=array_values(array_filter($employees,fn($employee)=>Auth::canAccessEmployee((int)$employee['id'])));foreach($employees as $employee){$exists=Database::fetch('SELECT id FROM hr_assessment_assignments WHERE test_id=? AND employee_id=? AND COALESCE(period_key,"")=? AND status IN ("assigned","in_progress","submitted")',[$testId,$employee['id'],$period]);if($exists)continue;Database::execute('INSERT INTO hr_assessment_assignments(test_id,employee_id,department,role_key,sales_line,supervisor_id,manager_id,assigned_by,assignment_scope,period_key,due_date,allow_retake,status,notes,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,"assigned",?,NOW(),NOW())',[$testId,$employee['id'],$employee['department'],$employee['role_key'],$employee['sales_line'],$employee['supervisor_id'],$employee['organization_manager_id'],(int)$user['id'],$scope,$period,$due,isset($_POST['allow_retake'])?1:0,trim($_POST['notes']??'')]);}flash($employees?'عملیات با موفقیت انجام شد.':'هیچ کارمندی با دامنه انتخابی یافت نشد.',$employees?'success':'danger');}catch(Throwable $e){error_log('Assessment assignment: '.$e->getMessage());flash('خطا در ذخیره‌سازی اطلاعات. لطفاً مجدد تلاش کنید.','danger');}redirect('/admin/employee-assessments.php');}
$tests=Database::fetchAll('SELECT * FROM hr_assessment_tests WHERE active=1 ORDER BY sort_order');$accessibleIds=HrModule::accessibleEmployeeIds($user);if(!$accessibleIds)$accessibleIds=[-1];$employeePlaceholders=implode(',',array_fill(0,count($accessibleIds),'?'));$employees=Database::fetchAll("SELECT id,name,department,role_key FROM users WHERE role='employee' AND status='active' AND id IN ($employeePlaceholders) ORDER BY name",$accessibleIds);$managers=Auth::isAdmin()?Database::fetchAll('SELECT id,name FROM users WHERE role="manager" AND status="active" ORDER BY name'):[];$counts=Database::fetch("SELECT (SELECT COUNT(*) FROM hr_assessment_tests WHERE active=1) tests,(SELECT COUNT(*) FROM hr_assessment_assignments WHERE employee_id IN ($employeePlaceholders) AND status IN ('assigned','in_progress')) active_assignments,(SELECT COUNT(*) FROM hr_assessment_assignments WHERE employee_id IN ($employeePlaceholders) AND status='submitted') completed,(SELECT COUNT(*) FROM hr_assessment_results WHERE employee_id IN ($employeePlaceholders) AND risk_level='نیازمند پیگیری') followups",array_merge($accessibleIds,$accessibleIds,$accessibleIds));$latest=Database::fetchAll("SELECT a.*,u.name employee_name,t.title test_title FROM hr_assessment_assignments a JOIN users u ON u.id=a.employee_id JOIN hr_assessment_tests t ON t.id=a.test_id WHERE a.employee_id IN ($employeePlaceholders) ORDER BY a.id DESC LIMIT 30",$accessibleIds);require __DIR__.'/../views/partials/admin-header.php';?>
<?php $metricRows=Database::fetchAll("SELECT t.code,r.normalized_scores_json FROM hr_assessment_results r JOIN hr_assessment_tests t ON t.id=r.test_id WHERE r.employee_id IN ($employeePlaceholders) AND t.code IN ('JOB_SATISFACTION','BURNOUT_ORG')",$accessibleIds);$metricValues=['JOB_SATISFACTION'=>[],'BURNOUT_ORG'=>[]];foreach($metricRows as $row){$scores=json_decode($row['normalized_scores_json']?:'{}',true);if(is_array($scores)&&$scores)$metricValues[$row['code']][]=array_sum($scores)/count($scores);}$metricAverage=fn($code)=>$metricValues[$code]?array_sum($metricValues[$code])/count($metricValues[$code]):0;?>
<div class="stats"><div class="stat-card"><span>آزمون‌های فعال</span><strong><?=e($counts['tests'])?></strong></div><div class="stat-card"><span>تخصیص‌های فعال</span><strong><?=e($counts['active_assignments'])?></strong></div><div class="stat-card"><span>تکمیل‌شده</span><strong><?=e($counts['completed'])?></strong></div><div class="stat-card"><span>میانگین رضایت شغلی</span><strong><?=e(number_format($metricAverage('JOB_SATISFACTION'),1))?>٪</strong></div><div class="stat-card"><span>میانگین ریسک فرسودگی</span><strong><?=e(number_format($metricAverage('BURNOUT_ORG'),1))?>٪</strong></div><div class="stat-card"><span>نیازمند پیگیری HR</span><strong><?=e($counts['followups'])?></strong></div></div>
<section class="card admin-form"><div class="section-heading-row"><div><h2>تخصیص آزمون</h2><p class="muted">دامنه گروهی به تخصیص‌های فردی و قابل کنترل تبدیل می‌شود.</p></div><a class="btn" href="/admin/hr-assessment-results.php">نتایج آزمون</a></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><div class="grid grid-3"><label class="form-field"><span>آزمون</span><select name="test_id" required><?php foreach($tests as $t):?><option value="<?=$t['id']?>"><?=e($t['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>دامنه</span><select name="assignment_scope" id="scope"><option value="employee">کارمند</option><option value="department">واحد</option><option value="role">نقش</option><option value="sales_line">لاین فروش</option><option value="supervisor_team">تیم سرپرست</option><option value="manager_team">تیم مدیر</option><option value="company">کل شرکت</option></select></label><label class="form-field" id="employeeScope"><span>کارمند</span><select name="scope_value"><?php foreach($employees as $e):?><option value="<?=$e['id']?>"><?=e($e['name'].' - '.($e['department']?:'بدون واحد'))?></option><?php endforeach?></select></label><label class="form-field"><span>دوره</span><input name="period_key"></label><label class="form-field"><span>مهلت</span><input class="jalali-date-input" name="due_date"></label><label class="checkbox-item"><input type="checkbox" name="allow_retake"> اجازه تکرار</label><label class="form-field"><span>یادداشت</span><input name="notes"></label></div><button class="btn btn-primary">تخصیص آزمون</button></form><p class="muted">برای دامنه‌های غیرفردی، مقدار واحد/نقش/لاین یا شناسه مدیر را در فیلد کارمند وارد کنید.</p></section>
<section class="card"><h2>آخرین تخصیص‌ها</h2><div class="table-wrap"><table><thead><tr><th>کارمند</th><th>آزمون</th><th>دوره</th><th>مهلت</th><th>وضعیت</th></tr></thead><tbody><?php foreach($latest as $a):?><tr><td><?=e($a['employee_name'])?></td><td><?=e($a['test_title'])?></td><td><?=e($a['period_key']?:'-')?></td><td><?=e($a['due_date']?format_jalali_date($a['due_date']):'-')?></td><td><span class="badge"><?=e($a['status'])?></span></td></tr><?php endforeach?></tbody></table></div></section>
<script>
const scopeSelect=document.getElementById('scope'),scopeValue=document.querySelector('[name="scope_value"]');
const scopeInput=document.createElement('input');scopeInput.type='text';scopeInput.placeholder='نام واحد، کلید نقش، لاین یا شناسه مدیر';scopeInput.hidden=true;scopeValue.closest('label').append(scopeInput);
function syncScope(){const individual=scopeSelect.value==='employee';scopeValue.hidden=!individual;scopeInput.hidden=individual;scopeInput.required=!individual&&scopeSelect.value!=='company'}scopeSelect.addEventListener('change',syncScope);syncScope();
scopeSelect.form.addEventListener('submit',()=>{if(scopeSelect.value!=='employee'){const option=document.createElement('option');option.value=scopeInput.value;option.textContent=scopeInput.value;scopeValue.append(option);scopeValue.value=scopeInput.value}});
</script>
</section></main></div><script src="/assets/js/app.js"></script></body></html>
